        return ARCHIVE_EOF;
    }

    enum LOCATOR_FLAGS {
        QLIST = 0x01, RECOVERY = 0x02,
    };

    if(locator_flags & QLIST) {
        if(!read_var(a, &rar->qlist_offset, NULL)) {
            return ARCHIVE_EOF;
        }

        /* qlist is not used */
    }

    if(locator_flags & RECOVERY) {
        if(!read_var(a, &rar->rr_offset, NULL)) {
            return ARCHIVE_EOF;
        }

        /* rr is not used */
    }

    return ARCHIVE_OK;
}

